{"edits":[{"path":"shared/task-ledger-working-context.ts","content":"export type TaskLedgerStatus = 'pending' | 'accepted' | 'rejected';

export interface TaskLedgerEvent {
  eventId: string;
  batchIdempotencyKey: string;
  type: string;
  status?: TaskLedgerStatus | string;
  taskId?: string;
  payload?: Record<string, unknown>;
  createdAt?: string;
  [key: string]: unknown;
}

export interface TaskLedgerTask {
  taskId: string;
  status: TaskLedgerStatus | string;
  eventId: string;
  batchIdempotencyKey: string;
  type: string;
  payload?: Record<string, unknown>;
  createdAt?: string;
}

export interface TaskLedgerProjection {
  tasks: Record<string, TaskLedgerTask>;
  pending: TaskLedgerTask[];
  accepted: TaskLedgerTask[];
  rejected: TaskLedgerTask[];
}

const knownStatuses = new Set(['pending', 'accepted', 'rejected']);

function statusOf(event: TaskLedgerEvent): TaskLedgerStatus | string {
  const candidate = event.status ?? event.payload?.status;
  return typeof candidate === 'string' ? candidate : 'pending';
}

function taskIdOf(event: TaskLedgerEvent): string | undefined {
  if (typeof event.taskId === 'string') return event.taskId;
  if (typeof event.payload?.taskId === 'string') return event.payload.taskId;
  return undefined;
}

/**
 * Projects the append-only ledger. The projection intentionally contains no
 * authoritative state: it can always be discarded and rebuilt from events.
 */
export function projectTaskLedgerEvents(events: readonly TaskLedgerEvent[]): TaskLedgerProjection {
  const tasks: Record<string, TaskLedgerTask> = {};

  for (const event of events) {
    const taskId = taskIdOf(event);
    if (!taskId) continue;
    tasks[taskId] = {
      taskId,
      status: statusOf(event),
      eventId: event.eventId,
      batchIdempotencyKey: event.batchIdempotencyKey,
      type: event.type,
      payload: event.payload,
      createdAt: event.createdAt,
    };
  }

  const all = Object.values(tasks);
  return {
    tasks,
    pending: all.filter((task) => task.status === 'pending'),
    accepted: all.filter((task) => task.status === 'accepted'),
    rejected: all.filter((task) => task.status === 'rejected'),
  };
}

export function isTaskLedgerEvent(value: unknown): value is TaskLedgerEvent {
  if (!value || typeof value !== 'object') return false;
  const event = value as Partial<TaskLedgerEvent>;
  return (
    typeof event.eventId === 'string' &&
    typeof event.batchIdempotencyKey === 'string' &&
    typeof event.type === 'string'
  );
}

export function serializeTaskLedgerEvent(event: TaskLedgerEvent): string {
  return `${JSON.stringify(event)}\n`;
}

export function parseTaskLedgerEvent(line: string): TaskLedgerEvent | undefined {
  try {
    const parsed: unknown = JSON.parse(line);
    return isTaskLedgerEvent(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

export function hasTerminalStatus(status: string): boolean {
  return knownStatuses.has(status);
}
