import path from 'node:path';
import {
  parseTaskLedgerEvent,
  projectTaskLedgerEvents,
  serializeTaskLedgerEvent,
  type TaskLedgerEvent,
  type TaskLedgerProjection,
} from '../../shared/task-ledger-working-context';

export interface TaskLedgerWorkingContextOptions {
  workspaceId: string;
  workspaceRoot: string;
  ledgerFileName?: string;
  workspaceDirectoryName?: string;
}

export interface SubmitTaskLedgerBatchOptions {
  batchIdempotencyKey: string;
  events: readonly Omit<TaskLedgerEvent, 'batchIdempotencyKey'>[];
}

export interface AppendTaskLedgerEventOptions {
  batchIdempotencyKey: string;
  event: Omit<TaskLedgerEvent, 'batchIdempotencyKey'>;
}

/**
 * Working Context adapter over the existing workspace JSONL ledger.
 *
 * There is deliberately no cache, snapshot, database, or background process:
 * every read is replayed from the append-only file and every write is checked
 * against that same file for idempotency.
 */
export class TaskLedgerWorkingContext {
  readonly workspaceId: string;
  readonly workspaceRoot: string;
  readonly ledgerPath: string;

  private appendQueue: Promise<void> = Promise.resolve();

  constructor(options: TaskLedgerWorkingContextOptions) {
    if (!options.workspaceId) throw new Error('workspaceId is required');
    if (!options.workspaceRoot) throw new Error('workspaceRoot is required');
    this.workspaceId = options.workspaceId;
    this.workspaceRoot = path.resolve(options.workspaceRoot);

    const workspaceDirectoryName = options.workspaceDirectoryName ?? '.task-ledger';
    const ledgerFileName = options.ledgerFileName ?? 'ledger.jsonl';
    const encodedWorkspaceId = encodeURIComponent(options.workspaceId);
    this.ledgerPath = path.join(
      this.workspaceRoot,
      workspaceDirectoryName,
      encodedWorkspaceId,
      ledgerFileName,
    );
  }

  private async ensureLedgerDirectory(): Promise<void> {
    await mkdir(path.dirname(this.ledgerPath), { recursive: true });
  }

  private async readEventsFromDisk(): Promise<TaskLedgerEvent[]> {
    let contents: string;
    try {
      contents = await readFile(this.ledgerPath, 'utf8');
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
      throw error;
    }

    const events: TaskLedgerEvent[] = [];
    for (const line of contents.split(/\r?\n/u)) {
      if (!line.trim()) continue;
      const event = parseTaskLedgerEvent(line);
      if (event) events.push(event);
    }
    return events;
  }

  async readEvents(): Promise<TaskLedgerEvent[]> {
    return this.readEventsFromDisk();
  }

  async getProjection(): Promise<TaskLedgerProjection> {
    return projectTaskLedgerEvents(await this.readEventsFromDisk());
  }

  async project(): Promise<TaskLedgerProjection> {
    return this.getProjection();
  }

  async appendEvent(options: AppendTaskLedgerEventOptions): Promise<TaskLedgerEvent> {
    if (!options.batchIdempotencyKey) {
      throw new Error('batchIdempotencyKey is required');
    }

    const event: TaskLedgerEvent = {
      ...options.event,
      batchIdempotencyKey: options.batchIdempotencyKey,
    };

    let resolveResult!: (value: TaskLedgerEvent) => void;
    let rejectResult!: (reason: unknown) => void;
    const result = new Promise<TaskLedgerEvent>((resolve, reject) => {
      resolveResult = resolve;
      rejectResult = reject;
    });

    const operation = this.appendQueue.then(async () => {
      await this.ensureLedgerDirectory();
      const existing = await this.readEventsFromDisk();
      const duplicate = existing.find(
        (candidate) => candidate.batchIdempotencyKey === options.batchIdempotencyKey,
      );
      if (duplicate) {
        resolveResult(duplicate);
        return;
      }

      await appendFile(this.ledgerPath, serializeTaskLedgerEvent(event), {
        encoding: 'utf8',
        flag: 'a',
      });
      resolveResult(event);
    });

    this.appendQueue = operation.then(
      () => undefined,
      () => undefined,
    );

    try {
      await operation;
      return await result;
    } catch (error) {
      rejectResult(error);
      throw error;
    }
  }

  async append(options: AppendTaskLedgerEventOptions): Promise<TaskLedgerEvent> {
    return this.appendEvent(options);
  }

  async submitBatch(options: SubmitTaskLedgerBatchOptions): Promise<TaskLedgerEvent[]> {
    if (!options.batchIdempotencyKey) {
      throw new Error('batchIdempotencyKey is required');
    }
    if (options.events.length === 0) return [];

    const existing = await this.readEventsFromDisk();
    const priorBatch = existing.filter(
      (event) => event.batchIdempotencyKey === options.batchIdempotencyKey,
    );
    if (priorBatch.length > 0) return priorBatch;

    const appended: TaskLedgerEvent[] = [];
    for (const candidate of options.events) {
      appended.push(
        await this.appendEvent({
          batchIdempotencyKey: options.batchIdempotencyKey,
          event: candidate,
        }),
      );
    }
    return appended;
  }

  async commit(options: SubmitTaskLedgerBatchOptions): Promise<TaskLedgerEvent[]> {
    return this.submitBatch(options);
  }
}

export default TaskLedgerWorkingContext;
"}]}

